"""Generated by solo-to-scale; edit `templates/tools/tests/test_approval.py` in the plugin, then run upgrade.

Founder approval gates: only the founder's own words approve, and every unclear case fails closed.
"""
from __future__ import annotations

import json
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

TOOLS = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(TOOLS))
import approval  # noqa: E402

REPO = "acme/example-startup"
FOUNDER = {"user": {"login": "acme"}}
OTHER = {"user": {"login": "someone-else"}}
BOT = {"user": {"login": "github-actions[bot]"}}
GATES = {"founders": [], "gates": {
    "deploy": {"mode": "ask", "what": "Deploy", "paths": ["render.yaml", ".github/workflows/deploy*"]},
    "external": {"mode": "ask", "what": "Publish", "paths": []},
    "budget": {"mode": "allow", "what": "Budget", "paths": []},
    "secrets": {"mode": "off", "what": "Secrets", "paths": []}}}


def c(who: dict, body: str) -> dict:
    return {**who, "body": body}


@pytest.fixture()
def root(tmp_path: Path) -> Path:
    (tmp_path / "founder").mkdir()
    (tmp_path / "founder/gates.json").write_text(json.dumps(GATES), encoding="utf-8")
    (tmp_path / "founder/project.json").write_text(json.dumps({"name": "Example Startup", "repo": REPO}), encoding="utf-8")
    return tmp_path


class FakeGitHub:
    def __init__(self) -> None:
        self.issues: dict[int, dict] = {}
        self.comments: dict[int, list] = {}
        self.events: dict[int, list] = {}
        self.files: dict[int, list] = {}
        self.created: list[dict] = []

    def __call__(self, *args: str, payload: dict | None = None):
        path = args[0].split("?")[0].removeprefix(f"repos/{REPO}/")
        if path == "issues" and payload is not None:
            n = 100 + len(self.created)
            self.created.append(payload)
            return {"number": n, "html_url": f"https://github.com/{REPO}/issues/{n}"}
        if path == "issues":
            want = args[0].split("labels=")[1].split("&")[0].split(",") if "labels=" in args[0] else []
            return [i for i in self.issues.values() if all(w in [lb["name"] for lb in i["labels"]] for w in want)]
        parts = path.split("/")
        n = int(parts[1])
        if parts[0] == "issues" and len(parts) == 2:
            return self.issues[n]
        if parts[-1] == "comments":
            return self.comments.get(n, [])
        if parts[-1] == "events":
            return self.events.get(n, [])
        if parts[-1] == "files":
            return [{"filename": f} for f in self.files.get(n, [])]
        raise AssertionError(f"unexpected call {args}")


@pytest.fixture()
def fake(monkeypatch: pytest.MonkeyPatch) -> FakeGitHub:
    f = FakeGitHub()
    monkeypatch.setattr(approval, "gh", f)
    monkeypatch.delenv("GITHUB_REPOSITORY", raising=False)
    return f


def add_request(f: FakeGitHub, n: int, gate: str, comments: list, scope: str = "this action only") -> None:
    f.issues[n] = {"number": n, "title": f"[approval] {gate}", "body": f"**Scope:** {scope}\n",
                   "labels": [{"name": "needs-founder"}, {"name": f"gate:{gate}"}]}
    f.comments[n] = comments


def test_only_the_founders_latest_command_counts():
    who = {"acme"}
    assert approval.decide([c(OTHER, "/approve"), c(BOT, "/approve always")], who)["state"] == "waiting"
    assert approval.decide([c(FOUNDER, "looks good"), c(FOUNDER, "LGTM, ship it")], who)["state"] == "waiting"
    assert approval.decide([c(FOUNDER, "/approve")], who) == {"state": "approved", "kind": "once", "note": ""}
    assert approval.decide([c(FOUNDER, "/approve always")], who)["kind"] == "always"
    assert approval.decide([c(FOUNDER, "/approve"), c(FOUNDER, "/reject too costly")], who) == \
        {"state": "rejected", "kind": "", "note": "too costly"}
    assert approval.decide([c(FOUNDER, "/approve always"), c(FOUNDER, "/revoke")], who)["state"] == "revoked"
    assert approval.decide([c(FOUNDER, "/approve"), c(OTHER, "/reject")], who)["state"] == "approved"
    assert approval.decide([c(FOUNDER, "Please don't /approve this yet")], who)["state"] == "waiting"


def test_founders_default_to_the_repo_owner_and_can_be_listed():
    assert approval.founders({"founders": []}, REPO) == {"acme"}
    assert approval.founders({"founders": ["cofounder"]}, REPO) == {"cofounder"}


def test_request_respects_the_gate_mode(root, fake, capsys):
    assert approval.main(["request", "budget", "--title", "x", "--root", str(root)]) == approval.APPROVED
    assert approval.main(["request", "secrets", "--title", "x", "--root", str(root)]) == approval.NO
    assert approval.main(["request", "nope", "--title", "x", "--root", str(root)]) == approval.ERROR
    assert fake.created == []
    assert approval.main(["request", "external", "--title", "Launch post", "--why", "launch day",
                          "--scope", "launch post on LinkedIn", "--role", "growth", "--root", str(root)]) == approval.WAITING
    made = fake.created[0]
    assert made["labels"] == ["needs-founder", "gate:external"] and made["title"] == "[approval] Launch post"
    assert "`/approve always`" in made["body"] and "**Scope:** launch post on LinkedIn" in made["body"]


def test_check_one_request(root, fake):
    add_request(fake, 7, "external", [c(OTHER, "/approve")])
    run = lambda *a: approval.main(["check", *a, "--root", str(root)])  # noqa: E731
    assert run("external", "--issue", "7") == approval.WAITING
    fake.comments[7].append(c(FOUNDER, "/approve"))
    assert run("external", "--issue", "7") == approval.APPROVED
    assert run("deploy", "--issue", "7") == approval.NO, "an approval for one gate never covers another"
    fake.comments[7].append(c(FOUNDER, "/reject changed my mind"))
    assert run("external", "--issue", "7") == approval.NO


def test_standing_rules_match_gate_and_scope_until_revoked(root, fake):
    run = lambda *a: approval.main(["check", *a, "--root", str(root)])  # noqa: E731
    add_request(fake, 8, "external", [c(FOUNDER, "/approve")], scope="weekly newsletter")
    assert run("external", "--scope", "weekly newsletter") == approval.WAITING, "a one-off is not a rule"
    fake.comments[8].append(c(FOUNDER, "/approve always"))
    assert run("external", "--scope", "weekly newsletter") == approval.APPROVED
    assert run("external", "--scope", "press release") == approval.WAITING
    assert run("deploy", "--scope", "weekly newsletter") == approval.WAITING
    fake.comments[8].append(c(FOUNDER, "/revoke"))
    assert run("external", "--scope", "weekly newsletter") == approval.WAITING
    assert run("secrets") == approval.NO and run("budget") == approval.APPROVED


def test_pull_requests_with_gated_files_need_the_founder_label(root, fake):
    run = lambda: approval.main(["pr", "5", "--root", str(root)])  # noqa: E731
    fake.files[5] = ["README.md"]
    assert run() == approval.APPROVED
    fake.files[5] = ["README.md", "render.yaml"]
    assert run() == approval.NO
    label = {"name": "founder-approved"}
    fake.events[5] = [{"event": "labeled", "label": label, "actor": {"login": "someone-else"}}]
    assert run() == approval.NO, "only a founder's label counts"
    fake.events[5].append({"event": "labeled", "label": label, "actor": {"login": "acme"}})
    assert run() == approval.APPROVED
    fake.events[5].append({"event": "unlabeled", "label": label, "actor": {"login": "acme"}})
    assert run() == approval.NO


def test_fails_closed(root, fake, monkeypatch):
    def broken(*a, **k):
        raise subprocess.CalledProcessError(1, "gh")
    monkeypatch.setattr(approval, "gh", broken)
    assert approval.main(["check", "external", "--issue", "7", "--root", str(root)]) == approval.ERROR
    (root / "founder/gates.json").write_text("not json", encoding="utf-8")
    assert approval.main(["check", "external", "--root", str(root)]) == approval.NO
    (root / "founder/gates.json").unlink()
    assert approval.main(["check", "external", "--root", str(root)]) == approval.NO


def test_gated_paths_match_globs():
    pol = {"gates": GATES["gates"]}
    assert approval.gated_paths(pol, [".github/workflows/deploy-prod.yml", "src/app.py"]) == \
        {"deploy": [".github/workflows/deploy-prod.yml"]}


@pytest.mark.skipif(shutil.which("git") is None, reason="needs git")
def test_template_policy_is_valid_and_secrets_are_founder_only():
    pol = json.loads((TOOLS.parent / "founder" / "gates.json").read_text(encoding="utf-8"))
    modes = {name: g["mode"] for name, g in pol["gates"].items()}
    assert set(modes.values()) <= {"ask", "allow", "off"}
    assert modes["secrets"] == "off"
    assert {"hire", "budget", "deploy", "external", "spend", "decision", "pricing", "legal"} <= set(modes)
